import{_ as a,c as n,a as r,o as d}from"./app-BE5Bj6c3.js";const i={};function c(t,e){return d(),n("div",null,e[0]||(e[0]=[r('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-23-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-23-资讯日报"><span>2026-09-23 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="meta-muse爆红-扎克伯格身价大涨" tabindex="-1"><a class="header-anchor" href="#meta-muse爆红-扎克伯格身价大涨"><span>Meta Muse爆红 扎克伯格身价大涨</span></a></h3><p>Meta调整AI战略，放弃跟OpenAI拼基础模型跑分，推出可后台执行任务的个人AI Agent Muse，上线两周爆火，扎克伯格身价大涨，Meta剑指下一代计算平台入口，正面临多重竞争。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86f511feffa81f77b6ad5f0814a13090c6f74290b42d6b0aacd8b86da698319ba0dea132b681&amp;idx=1&amp;mid=2649806030&amp;sn=ae84957f70e46f38fce5ca332e2da727#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="agent时代-cpu价值该重估了" tabindex="-1"><a class="header-anchor" href="#agent时代-cpu价值该重估了"><span>Agent时代，CPU价值该重估了</span></a></h3><p>英特尔判断：Agent时代AI算力配比从CPU:GPU=1:4变为1:1，CPU需承担更多调度、预处理工作，价值需要重估，该判断获资本市场认可，给英特尔带来新业务机会。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e92c60c5b8ea4692cbd6cd85070527aedd215cc87843946f1317b7dedba35e551fa465db4a14&amp;idx=3&amp;mid=2247926174&amp;sn=bffcf96b6d407dd048f6205755c163e4#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="小华智慧成立-ai赋能会展升级" tabindex="-1"><a class="header-anchor" href="#小华智慧成立-ai赋能会展升级"><span>小华智慧成立 AI赋能会展升级</span></a></h3><p>大新华会展推出旗下小华智慧，发布会展行业首个自研AI4MICE平台，践行“ALL IN AI”战略，以硅碳协同推动会展业数智化，探索行业人机协同新模式。<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjEyNzQyMw==&amp;chksm=86639cc620f9d613d083ff2262d469bf3c89db86013ed70e54373929f69b5c1e75b634e5cc81&amp;idx=1&amp;mid=2649906565&amp;sn=a6c4c836375cf42a177dc1fcde277361#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="redis之父质疑jev狂热-多数开发者不需要" tabindex="-1"><a class="header-anchor" href="#redis之父质疑jev狂热-多数开发者不需要"><span>Redis之父质疑Jev狂热：多数开发者不需要</span></a></h3><p>Redis之父antirez称Jev热度虚高，AI泡沫里多数人分不清轻重，绝大多数开发者不需要它。Jev主打低延迟低成本结构化分类，能力边界清晰，仅适合简单判断。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc2e90aa704bc454422e425a802a408098ead48bfe1a49534b161b2bf78082e0cb1733d2a80d&amp;idx=1&amp;mid=2651293583&amp;sn=583352a3f325873418ec9278224f4f05#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="首期斜杠青年ai夜课即将收官" tabindex="-1"><a class="header-anchor" href="#首期斜杠青年ai夜课即将收官"><span>首期斜杠青年AI夜课即将收官</span></a></h3><p>Joker称不必硬补AI工具短板，要用导演思维绕开缺陷，叙事能力与人文洞察才是创作者不可替代的底牌；卢九霖认为创作本质是生命学，灵感源于真实生命体验，首期夜课9月24日收官。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3OTQyMDE4NA==&amp;chksm=ce25b4af6467515cb7aa9174d9fe2dd6884aa772124338924e6d39bae1589e4b0902b0ebefb2&amp;idx=1&amp;mid=2247617831&amp;sn=092ba085fbe5f63a3fb171dc933af4b8#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="grok-4-7发布-网友造火箭玩" tabindex="-1"><a class="header-anchor" href="#grok-4-7发布-网友造火箭玩"><span>Grok 4.7发布 网友造火箭玩</span></a></h3><p>xAI错峰发布Grok 4.7，升级50万Token上下文，重点强化编码、Agent与复杂长任务，多项测试成绩提升，加量不加价，网友花式整活造火箭，也曝出小bug。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9e2cd7f31bd020e80e59db85afd8aa4cc7a17360dc7bc49a4c68d1c0c3f6949e2fb56432f06&amp;idx=2&amp;mid=2247926174&amp;sn=cfaf8201badd3b719fad3acc7802e256#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="专访三菱电机-sic与igbt双轨并行" tabindex="-1"><a class="header-anchor" href="#专访三菱电机-sic与igbt双轨并行"><span>专访三菱电机：SiC与IGBT双轨并行</span></a></h3><p>赤田智史：三菱电机坚持SiC与IGBT双轨并行战略，按场景适配不同产品，将扩充SiC产能，聚焦差异化服务中国市场，推进三家功率半导体业务整合。<a href="https://mp.weixin.qq.com/s?__biz=MzIwMzgzNTQ1Nw==&amp;chksm=971eea01a5d09a2e88ff030cf042bba778626d45eb894b9343945b526c23efdafbfd48db1b8e&amp;idx=1&amp;mid=2247661761&amp;sn=9a44afcef42f52190e2a49ca9c07bac3#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="支付宝千万悬赏生活类ai智能体" tabindex="-1"><a class="header-anchor" href="#支付宝千万悬赏生活类ai智能体"><span>支付宝千万悬赏生活类AI智能体</span></a></h3><p>蚂蚁集团CEO韩歆毅称，8小时外生活智能体爆发是必然，智能体商业6-12个月内将迎来爆发。支付宝投千万悬赏，开放生态助力开发者实现商业闭环，抢滩未来服务入口。<a href="https://mp.weixin.qq.com/s?__biz=MzYyMTY1NDA0Nw==&amp;chksm=fe512c1fc8af16aa7af99ba56a2ae8fba99e33034f22d7f98b705b8f9bbfe8aa9efa89f84631&amp;idx=1&amp;mid=2247521564&amp;sn=44a7b6109fcfd8d3cd7fda3401e5b412#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="千问推出qwen-intelligence-ai手机方案" tabindex="-1"><a class="header-anchor" href="#千问推出qwen-intelligence-ai手机方案"><span>千问推出Qwen Intelligence AI手机方案</span></a></h3><p>阿里千问推出AI手机全栈方案Qwen Intelligence，不做硬件，为手机厂商提供三大Agent与开放评测集，已联合荣耀落地，让AI手机可主动处理复杂任务。<a href="https://mp.weixin.qq.com/s?__biz=Mzk0ODg4NDI5NA==&amp;chksm=c221d53f37fc519ba93d0b288a27e3b3119fbf6d2a0944b4e7f8d6cd0dce6f9f6b17ab850401&amp;idx=1&amp;mid=2247490602&amp;sn=b3bbf1315b95a17fe2936a07da4e50b2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="阿里发布新一代多模态大模型家族" tabindex="-1"><a class="header-anchor" href="#阿里发布新一代多模态大模型家族"><span>阿里发布新一代多模态大模型家族</span></a></h3><p>阿里巴巴淘天首席科学家郑波称，三年内将出现原生全模态统一模型，打破模态边界；本次阿里发布多模态新模型家族，推动多模态从生成内容走向创造体验，重构专业内容生产。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bcd76a6987866540b233b644a24c620c1d4d1f5680bab0f64e48daffcdbfc03ecb9ea3f0f5d3&amp;idx=1&amp;mid=2651293633&amp;sn=f4280e8e1b8500ddf2ba110911825eae#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="乐享以太大模型-定义中国具身智能" tabindex="-1"><a class="header-anchor" href="#乐享以太大模型-定义中国具身智能"><span>乐享以太大模型，定义中国具身智能</span></a></h3><p>乐享科技推出以太大模型，一改具身智能主流路线的预测范式，采用能量驱动求解范式，经开放环境测试验证，可在不确定环境自主决策，开辟Physical AI新路线，推动中国具身智能突围。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91102bdae5133bc5dcbe7a4ea1927fdc1d47063667de7fc1b7a545b723dfc0da3a097bf7c334&amp;idx=1&amp;mid=2247746041&amp;sn=fff33861283f1d504ee99b03b8ce3348#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="gpt-6-astra刷屏-3d生成规则改写" tabindex="-1"><a class="header-anchor" href="#gpt-6-astra刷屏-3d生成规则改写"><span>GPT-6 Astra刷屏，3D生成规则改写</span></a></h3><p>影眸Hyper3D认为，通用大模型负责拆解任务规划路径，专业3D模型负责生成复杂高质量资产，3D生成竞争核心已转向适配Agent的可调用可迭代能力。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9fde5f96b7ffd149705009e0716341200cd8841fc5db82f93f29ff2cfd078a530537f1dfcf3&amp;idx=1&amp;mid=2247926171&amp;sn=86796a912ccee1c4d1d7fcf2a94d2382#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="gpt-6控机器人-具身落地没那么简单" tabindex="-1"><a class="header-anchor" href="#gpt-6控机器人-具身落地没那么简单"><span>GPT-6控机器人？具身落地没那么简单</span></a></h3><p>Robocurve测试显示GPT-6 Astra控制机器人成功率达95%，远优于Fable 5.1，但RoboDojo真机测试中Astra频繁出现不安全动作，未能完成评测。穹彻智能发布RoboRSI解决具身系统稳定运行痛点<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85c2d3fcd5df52f2d1400a43a93247636fea89d92e9ef5716857a2cd979108bf6e2a99efb47d&amp;idx=1&amp;mid=2651059152&amp;sn=81dd2274b1d881df85d42dd3c710d1d2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="小米烧347万训出开源第一大模型" tabindex="-1"><a class="header-anchor" href="#小米烧347万训出开源第一大模型"><span>小米烧347万训出开源第一大模型</span></a></h3><p>花叔实测：小米花347万美元做RL后训练的MiMo-V2.6，拿下开源模型智能榜第一，多真实场景测试能力在线，缓存命中率高，使用成本极低，性价比突出。<a href="https://mp.weixin.qq.com/s?__biz=Mzg2OTA1OTAxNA==&amp;chksm=cfc79c7a270565555451588b1e8418fef99b8ac99801a5de83399d9d7ecd843add5ac06d1812&amp;idx=1&amp;mid=2247492244&amp;sn=b154be185d6b0b051ede1a5c61852b92#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="snowflake大会的三个ai新变化" tabindex="-1"><a class="header-anchor" href="#snowflake大会的三个ai新变化"><span>Snowflake大会的三个AI新变化</span></a></h3><p>郭炜：Snowflake上海大会透出三个关键变化：AI Agent需配“工号”做制度化管理才能进企业，数据平台从记录变行动，Snowflake靠开放建Agent时代新护城河。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc17394e51e66216eb71fcc9ec45fb57a36ec0053fd3a30d3937315862ddab3cace372e359c9&amp;idx=3&amp;mid=2651293633&amp;sn=053637f37ad6d95a3738ec5c8d64f36e#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="姚顺宇施天麟-rsi验证比迭代难" tabindex="-1"><a class="header-anchor" href="#姚顺宇施天麟-rsi验证比迭代难"><span>姚顺宇施天麟：RSI验证比迭代难</span></a></h3><p>姚顺宇、施天麟等业内专家指出，RSI不止是模型单方面改进，是整套系统工程，当前RSI落地最难的不是实现自我迭代，而是验证迭代有效性，定义问题远难于解决问题。<a href="https://mp.weixin.qq.com/s?__biz=MzY5ODQwMTkxNA==&amp;chksm=f5a0abcd4de737676f8bf89a75fc50f285e045113f65805f03b4afed99c9897fb2f814fb283f&amp;idx=1&amp;mid=2247517029&amp;sn=d5036103652abf17d146ae712e3dc220#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="不受控agent凭什么上生产系统" tabindex="-1"><a class="header-anchor" href="#不受控agent凭什么上生产系统"><span>不受控Agent凭什么上生产系统？</span></a></h3><p>王一鹏：AI Agent落地生产核心痛点是失控，现有方案仅解决建造问题，亚马逊云科技提出以评估为核心的Agent DLC方法论，已帮助多家企业实现Agent稳定上线生产。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc1e36396ec51bf231596c51c14bcdae63b12614cb8d9c9e20e7e88a6a331acbfebbfbd7817a&amp;idx=1&amp;mid=2651293626&amp;sn=2fab3adbd86b315a4a37e76b6a518b8b#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯15年工程师转战大模型推理" tabindex="-1"><a class="header-anchor" href="#腾讯15年工程师转战大模型推理"><span>腾讯15年工程师转战大模型推理</span></a></h3><p>吴银光：AI浪潮下传统后台工程师的系统经验被低估，转型切入大模型推理业务层、Agent Infra是绝佳方向，放下头衔从零出发是抓住机遇的好选择。<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODYwMjI2MA==&amp;chksm=bf29532b163a0c2089c3a77f537308c7aee07c7260aca89dcd9b22ed27efa969ff729778254e&amp;idx=1&amp;mid=2649804238&amp;sn=5071d1c07d4c99fac83cbfe0a3860344#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="聊天ai价值-不如程序员一个for循环" tabindex="-1"><a class="header-anchor" href="#聊天ai价值-不如程序员一个for循环"><span>聊天AI价值 不如程序员一个for循环</span></a></h3><p>前OpenAI核心研究员Diogo Almeida：当前全行业把算力砸在教AI陪人类聊天，产出多是满嘴漂亮话的幻觉模型，AI真正的价值是成为软件底层决策基础设施，输出可靠结果创造真实经济价值。<a href="https://mp.weixin.qq.com/s?__biz=Mzg4NDQwNTI0OQ==&amp;chksm=ce2e7dcdcc8f87d09726641396998ea2cf52b612a8cd09b20a24298fa6b64f13eaa0dc6b3b3b&amp;idx=1&amp;mid=2247590764&amp;sn=f15e9829ddd379c2d80ae82d6d9dd52d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="一线ai研究员聊蒸馏变难后的方向" tabindex="-1"><a class="header-anchor" href="#一线ai研究员聊蒸馏变难后的方向"><span>一线AI研究员聊蒸馏变难后的方向</span></a></h3><p>多家头部模型厂一线研究员闭门交流：当前模型蒸馏难度提升，专家专业训练数据价值凸显，Kernel优化是RSI现阶段最优落地场景，数据供应商需提前布局垂直领域专业数据。<a href="https://mp.weixin.qq.com/s?__biz=Mzg2OTY0MDk0NQ==&amp;chksm=cf12cf1231970892d13186f6e2157fc39ea0bcfff1c6b8b5d7f6c0ec0ec24b707cd348968624&amp;idx=1&amp;mid=2247527326&amp;sn=0a12e5026295e3a66392b1468144b36a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="小米6天烧2000万拿下开源第一大模型" tabindex="-1"><a class="header-anchor" href="#小米6天烧2000万拿下开源第一大模型"><span>小米6天烧2000万拿下开源第一大模型</span></a></h3><p>小米6天投入超2000万完成MiMo-V2.6强化学习训练，MiMo-V2.6-Pro登顶全球开源大模型第一，部分Agent能力超越头部闭源模型，全套技术全开源，大幅缩小开源闭源差距。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9eda6f645c7f1682ab1ce9285279917472f2fd0215cd5a21a9696bd494c4a75344be7fcae8f&amp;idx=1&amp;mid=2247926093&amp;sn=e017a8ac34f7ab12911ce17ae385a1af#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_1g内存就能跑的本地决策ai" tabindex="-1"><a class="header-anchor" href="#_1g内存就能跑的本地决策ai"><span>1G内存就能跑的本地决策AI</span></a></h3><p>开发者推出适配Apple MLX的Laya-MLX，它是开源Jev平替Laya的本地版本，421M参数版仅需不到1G内存就能在Mac本地运行，速度快，准确率超原版Jev，适合短高频决策任务。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e925fa841dfb6a360a89d9d4edd8e836fe0528800769895fc6551a4043e6d57af231e99e4ce6&amp;idx=2&amp;mid=2247926050&amp;sn=536a5c678e48beb1072e08cbe31b75d7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openjiuwen发布首个开源智能体资产平台" tabindex="-1"><a class="header-anchor" href="#openjiuwen发布首个开源智能体资产平台"><span>openJiuwen发布首个开源智能体资产平台</span></a></h3><p>华为联合多方打造的openJiuwen推出首个开源智能体资产平台，将Agent能力拆分为五类可复用资源，跑通能力从创建到共享的完整生命周期，解决Agent能力难以沉淀复用的痛点，加速生产级落地。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85e5714c92c74d13a69bdee6d5ed139b36af950ac9b9ac4084dd5af2cf6ff91a1b12eaa9a7ba&amp;idx=2&amp;mid=2651059152&amp;sn=749ad51193995789f64cdff1b4bbcd98#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',54)]))}const s=a(i,[["render",c]]),f=JSON.parse('{"path":"/posts/2026-09-23.html","title":"AI日报：Meta Muse爆红 扎克伯格身价大涨; Agent时代，CPU价值该重估了; 小华智慧成立 AI赋能会展升级","lang":"zh-CN","frontmatter":{"date":"2026-09-23T00:00:00.000Z","title":"AI日报：Meta Muse爆红 扎克伯格身价大涨; Agent时代，CPU价值该重估了; 小华智慧成立 AI赋能会展升级"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"Meta Muse爆红 扎克伯格身价大涨","slug":"meta-muse爆红-扎克伯格身价大涨","link":"#meta-muse爆红-扎克伯格身价大涨","children":[]},{"level":3,"title":"Agent时代，CPU价值该重估了","slug":"agent时代-cpu价值该重估了","link":"#agent时代-cpu价值该重估了","children":[]},{"level":3,"title":"小华智慧成立 AI赋能会展升级","slug":"小华智慧成立-ai赋能会展升级","link":"#小华智慧成立-ai赋能会展升级","children":[]},{"level":3,"title":"Redis之父质疑Jev狂热：多数开发者不需要","slug":"redis之父质疑jev狂热-多数开发者不需要","link":"#redis之父质疑jev狂热-多数开发者不需要","children":[]},{"level":3,"title":"首期斜杠青年AI夜课即将收官","slug":"首期斜杠青年ai夜课即将收官","link":"#首期斜杠青年ai夜课即将收官","children":[]},{"level":3,"title":"Grok 4.7发布 网友造火箭玩","slug":"grok-4-7发布-网友造火箭玩","link":"#grok-4-7发布-网友造火箭玩","children":[]},{"level":3,"title":"专访三菱电机：SiC与IGBT双轨并行","slug":"专访三菱电机-sic与igbt双轨并行","link":"#专访三菱电机-sic与igbt双轨并行","children":[]},{"level":3,"title":"支付宝千万悬赏生活类AI智能体","slug":"支付宝千万悬赏生活类ai智能体","link":"#支付宝千万悬赏生活类ai智能体","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"千问推出Qwen Intelligence AI手机方案","slug":"千问推出qwen-intelligence-ai手机方案","link":"#千问推出qwen-intelligence-ai手机方案","children":[]},{"level":3,"title":"阿里发布新一代多模态大模型家族","slug":"阿里发布新一代多模态大模型家族","link":"#阿里发布新一代多模态大模型家族","children":[]},{"level":3,"title":"乐享以太大模型，定义中国具身智能","slug":"乐享以太大模型-定义中国具身智能","link":"#乐享以太大模型-定义中国具身智能","children":[]},{"level":3,"title":"GPT-6 Astra刷屏，3D生成规则改写","slug":"gpt-6-astra刷屏-3d生成规则改写","link":"#gpt-6-astra刷屏-3d生成规则改写","children":[]},{"level":3,"title":"GPT-6控机器人？具身落地没那么简单","slug":"gpt-6控机器人-具身落地没那么简单","link":"#gpt-6控机器人-具身落地没那么简单","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"小米烧347万训出开源第一大模型","slug":"小米烧347万训出开源第一大模型","link":"#小米烧347万训出开源第一大模型","children":[]},{"level":3,"title":"Snowflake大会的三个AI新变化","slug":"snowflake大会的三个ai新变化","link":"#snowflake大会的三个ai新变化","children":[]},{"level":3,"title":"姚顺宇施天麟：RSI验证比迭代难","slug":"姚顺宇施天麟-rsi验证比迭代难","link":"#姚顺宇施天麟-rsi验证比迭代难","children":[]},{"level":3,"title":"不受控Agent凭什么上生产系统？","slug":"不受控agent凭什么上生产系统","link":"#不受控agent凭什么上生产系统","children":[]},{"level":3,"title":"腾讯15年工程师转战大模型推理","slug":"腾讯15年工程师转战大模型推理","link":"#腾讯15年工程师转战大模型推理","children":[]},{"level":3,"title":"聊天AI价值 不如程序员一个for循环","slug":"聊天ai价值-不如程序员一个for循环","link":"#聊天ai价值-不如程序员一个for循环","children":[]},{"level":3,"title":"一线AI研究员聊蒸馏变难后的方向","slug":"一线ai研究员聊蒸馏变难后的方向","link":"#一线ai研究员聊蒸馏变难后的方向","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"小米6天烧2000万拿下开源第一大模型","slug":"小米6天烧2000万拿下开源第一大模型","link":"#小米6天烧2000万拿下开源第一大模型","children":[]},{"level":3,"title":"1G内存就能跑的本地决策AI","slug":"_1g内存就能跑的本地决策ai","link":"#_1g内存就能跑的本地决策ai","children":[]},{"level":3,"title":"openJiuwen发布首个开源智能体资产平台","slug":"openjiuwen发布首个开源智能体资产平台","link":"#openjiuwen发布首个开源智能体资产平台","children":[]}]}],"git":{},"filePathRelative":"posts/2026-09-23.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-23 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>Meta Muse爆红 扎克伯格身价大涨</h3>\\n<p>Meta调整AI战略，放弃跟OpenAI拼基础模型跑分，推出可后台执行任务的个人AI Agent Muse，上线两周爆火，扎克伯格身价大涨，Meta剑指下一代计算平台入口，正面临多重竞争。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86f511feffa81f77b6ad5f0814a13090c6f74290b42d6b0aacd8b86da698319ba0dea132b681&amp;idx=1&amp;mid=2649806030&amp;sn=ae84957f70e46f38fce5ca332e2da727#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,f as data};
